fn prepare(a:&A,eq:&[u32],path:&str)->(ffi::Native,Vec<u32>,bool){let mut keep=vec![false;a.nodes.len()];let mut stack=eq.to_vec();while let Some(i)=stack.pop(){if keep[i as usize]{continue;}keep[i as usize]=true;let x=a.nodes[i as usize];if x[0]>=2{stack.push(x[1]);stack.push(x[2]);}}let mut mapping=vec![0u32;a.nodes.len()];let mut count=0;for(i,node)in a.nodes.iter().enumerate(){if node[0]==1{count+=1;mapping[i]=count;}}assert_eq!(count as usize,a.inputs);mapping[0]=count+1;mapping[1]=count+2;count+=2;for(i,node)in a.nodes.iter().enumerate(){if keep[i]&&node[0]>=2{count+=1;mapping[i]=count;}}let mut native=ffi::Native::new(path,count as usize,a.inputs);let mut ok=native.clause(&[-(mapping[0]as i32)]);ok&=native.clause(&[mapping[1]as i32]);for(i,node)in a.nodes.iter().enumerate(){if !keep[i]{continue;}let z=mapping[i]as i32;if node[0]==2{ok&=native.xor(&[mapping[node[1]as usize],mapping[node[2]as usize],mapping[i]],false);}else if node[0]==3{let x=mapping[node[1]as usize]as i32;let y=mapping[node[2]as usize]as i32;ok&=native.clause(&[-x,-y,z]);ok&=native.clause(&[x,-z]);ok&=native.clause(&[y,-z]);}}for wire in eq{ok&=native.clause(&[-(mapping[*wire as usize]as i32)]);}let primary=a.nodes.iter().enumerate().filter(|(_,x)|x[0]==1).map(|(i,_)|mapping[i]).collect();(native,primary,ok)}
