fn native_controls(path:&str)->Value{let m=Model::new(2,N::from(7u32),N::zero(),N::one(),N::one(),N::zero());let(a,eq)=build(&m,1,8);let expected=(0..1usize<<a.inputs).filter_map(|mask|{let bits=(0..a.inputs).map(|i|mask>>i&1!=0).collect::<Vec<_>>();a.eval(&bits,&eq).then_some(bits)}).collect::<std::collections::BTreeSet<_>>();let(got,complete,_)=enumerate(&a,&eq,path,10.,4096);assert!(complete);assert_eq!(got.into_iter().collect::<std::collections::BTreeSet<_>>(),expected);json!({"status":"passed","native_tiny_primary_models":expected.len(),"native_complete":complete,"scope":"actual modified native CDCL adapter versus exhaustive tiny predicate"})}
fn load_model(path:&str)->(Model,usize){let data:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let n=data["extension_field"]["degree"].as_u64().unwrap()as usize;assert_eq!(n,83);let z=hx(data["target"]["x_hex"].as_str().unwrap());let yt=hx(data["target"]["y_hex"].as_str().unwrap())^&z;let m=Model::new(n,hx(data["extension_field"]["modulus_hex"].as_str().unwrap()),hx(data["curve"]["a_hex"].as_str().unwrap()),hx(data["curve"]["b_hex"].as_str().unwrap()),z,yt);let basis=data["source_basis_hex"].as_array().unwrap();assert_eq!(basis.len(),18);for(i,x)in basis.iter().enumerate(){assert_eq!(hx(x.as_str().unwrap()),N::one()<<i);}assert!(hx(data["source_offset_hex"].as_str().unwrap_or("0x0")).is_zero());(m,18)}
fn run(id:&str,fixture:&str,library:&str)->Value{let started=Instant::now();let(m,d)=load_model(fixture);let(a,eq)=build(&m,d,8);assert_eq!(a.inputs,174);let counts=reachable(&a,&eq);let remaining=60f64-started.elapsed().as_secs_f64();assert!(remaining>0.);let(models,complete,stats)=enumerate(&a,&eq,library,remaining,4096);let mut roots=vec![];for bits in models{let read=|offset:usize,n:usize|{let mut x=N::zero();for i in 0..n{if bits[offset+i]{x|=N::one()<<i;}}x};let xs=(0..5).map(|i|read(i*d,d)).collect::<Vec<_>>();let r=read(5*d,m.c.n);let hc=m.c.product(&xs);let(h,k,s,trace)=m.recover(&hc,&r,bits[5*d+m.c.n]);assert!(trace);assert_eq!(m.c.literal(&h,&k,&r,&s,&m.a,&m.b,&m.z,&m.yt),hc);roots.push(json!({"sources":xs.iter().map(|x|x.to_str_radix(16)).collect::<Vec<_>>(),"r":r.to_str_radix(16),"h":h.to_str_radix(16),"k":k.to_str_radix(16),"s":s.to_str_radix(16)}));}let exact=if complete{json!(roots.len())}else{Value::Null};json!({"schema":"scientific_result_v1","experiment_id":id,"status":if complete{"passed"}else{"inconclusive"},"summary":"Native primary-only CDCL searched the exact full norm predicate with literal model replay; original S3 completeness remains unclaimed.","evidence":{"norm_primary_search_complete":complete,"norm_primary_count_exact":exact,"verified_norm_primary_lower_bound":roots.len(),"verified_norm_models":roots,"circuit_counts":counts,"native_stats":stats,"backend":"modified CryptoMiniSat functional-primary Gaussian fork v2, source/hash pinned; not F4/F5/F6","original_root_count_exact":null,"original_auxiliary_fibers_reconstructed":false,"release_gate_claim":false,"scope":"norm predicate primary roots only; no global original field/ANF equivalence or original tuple count"},"next_actions":["Use native matrix/decision statistics to diagnose unresolved search; do not repeat identical failed execution.","Reconstruct every original ordered S3 auxiliary fiber and pay ghost/exception closure before original all-root claims.","Keep genuine matching F4/F5/F6 and qualified8x gate separate."]})}
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|x|x=="controls"){println!("{}",controls());return;}if a.get(1).is_some_and(|x|x=="native-controls"){println!("{}",native_controls(a.get(2).expect("library")));return;}let t=Instant::now();let mut r=run(a.get(1).expect("id"),a.get(2).expect("fixture"),a.get(3).expect("library"));let mut s=r.to_string();if t.elapsed().as_secs()>=70{r["status"]=json!("inconclusive");r["evidence"]["norm_primary_search_complete"]=json!(false);r["evidence"]["norm_primary_count_exact"]=Value::Null;s=r.to_string();}println!("{s}");}
